package com.acme.files.uploads;

/**
 * Rejects uploaded files that exceed the maximum allowed size for their category.
 */
public class FileSizeLimitGuard {

    private final CategoryLimits limits;

    public FileSizeLimitGuard(CategoryLimits limits) {
        this.limits = limits;
    }

    public void assertWithinLimit(String category, long sizeBytes) {
        long max = limits.maxBytesFor(category);
        if (sizeBytes > max) {
            throw new FileTooLargeException(category, sizeBytes, max);
        }
    }
}

class FileTooLargeException extends RuntimeException {
    public FileTooLargeException(String category, long size, long max) {
        super("File of " + size + " bytes exceeds " + max + " for " + category);
    }
}

