package com.acme.files.storage;

import java.io.InputStream;
import java.security.DigestInputStream;
import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;

/**
 * Computes a SHA-256 digest while streaming a file to storage.
 */
public class ChecksummingStorage {

    private final BlobStore blobStore;

    public ChecksummingStorage(BlobStore blobStore) {
        this.blobStore = blobStore;
    }

    public StoredFile store(InputStream in, String fileName) throws java.io.IOException {
        MessageDigest digest = sha256();
        DigestInputStream dis = new DigestInputStream(in, digest);
        String key = blobStore.write(fileName, dis);
        String checksum = toHex(digest.digest());
        return new StoredFile(key, checksum, blobStore.sizeOf(key));
    }

    private MessageDigest sha256() {
        try {
            return MessageDigest.getInstance("SHA-256");
        } catch (NoSuchAlgorithmException e) {
            throw new IllegalStateException("SHA-256 unavailable", e);
        }
    }

    private String toHex(byte[] bytes) {
        return java.util.HexFormat.of().formatHex(bytes);
    }
}

