package com.acme.files.web;

import org.springframework.web.bind.annotation.PostMapping;
import org.springframework.web.bind.annotation.RequestParam;
import org.springframework.web.bind.annotation.RestController;
import org.springframework.web.multipart.MultipartFile;

/**
 * Upload endpoint: validate, store with checksum, record metadata.
 */
@RestController
public class FileUploadController {

    private final FileSizeLimitGuard sizeGuard;
    private final MimeTypeGuard mimeGuard;
    private final ChecksummingStorage storage;
    private final FileMetadataRepository metadata;

    public FileUploadController(FileSizeLimitGuard sizeGuard, MimeTypeGuard mimeGuard,
                                ChecksummingStorage storage, FileMetadataRepository metadata) {
        this.sizeGuard = sizeGuard;
        this.mimeGuard = mimeGuard;
        this.storage = storage;
        this.metadata = metadata;
    }

    @PostMapping("/files")
    public FileReference upload(@RequestParam String category,
                                @RequestParam MultipartFile file) throws java.io.IOException {
        sizeGuard.assertWithinLimit(category, file.getSize());
        mimeGuard.assertAllowed(category, file.getContentType());
        StoredFile stored = storage.store(file.getInputStream(), file.getOriginalFilename());
        FileMetadata m = metadata.save(FileMetadata.of(stored, file.getOriginalFilename(), category));
        return new FileReference(m.getId(), stored.getKey());
    }
}

