package com.acme.reports.exports;

import java.io.Writer;
import java.time.LocalDate;
import java.util.List;

/**
 * Streams a CSV export of orders over a selected date range.
 */
public class OrderCsvReportGenerator {

    private final OrderRepository orders;

    public OrderCsvReportGenerator(OrderRepository orders) {
        this.orders = orders;
    }

    public void write(LocalDate from, LocalDate to, Writer out) throws java.io.IOException {
        if (to.isBefore(from)) {
            throw new IllegalArgumentException("End date before start date");
        }
        out.write("order_id,customer_id,placed_on,total,status\n");
        List<Order> rows = orders.findPlacedBetween(from, to);
        for (Order o : rows) {
            out.write(escape(o.getId()) + "," + escape(o.getCustomerId()) + "," +
                      o.getPlacedOn() + "," + o.getTotal() + "," + o.getStatus() + "\n");
        }
        out.flush();
    }

    private String escape(String s) {
        return s == null ? "" : s.replace(",", "\\,");
    }
}

