package com.acme.reports.scheduling;

import java.time.ZonedDateTime;

/**
 * Registers a recurring report generation and delivery schedule.
 */
public class ReportScheduleService {

    private final ScheduleRepository schedules;
    private final RecurrenceCalculator recurrence;
    private final NotificationGateway notifier;

    public ReportScheduleService(ScheduleRepository schedules, RecurrenceCalculator recurrence, NotificationGateway notifier) {
        this.schedules = schedules;
        this.recurrence = recurrence;
        this.notifier = notifier;
    }

    public ReportSchedule schedule(String reportId, String cron, java.util.List<String> recipients) {
        if (!recurrence.isValidCron(cron)) {
            throw new IllegalArgumentException("Invalid cron expression: " + cron);
        }
        ZonedDateTime next = recurrence.nextRun(cron, ZonedDateTime.now());
        ReportSchedule s = new ReportSchedule(reportId, cron, recipients, next);
        schedules.save(s);
        notifier.send(recipients.get(0), "Report schedule registered");
        return s;
    }
}

