/**
 * Persists a data-access audit row for report and file actions.
 */
public class DataAccessAuditor {

    private final EntityManager em;

    public DataAccessAuditor(EntityManager em) {
        this.em = em;
    }

    public void record(String userId, String resourceType, String resourceId, String action) {
        EntityTransaction tx = em.getTransaction();
        tx.begin();
        try {
            DataAccessEntry e = new DataAccessEntry();
            e.setUserId(userId);
            e.setResourceType(resourceType);
            e.setResourceId(resourceId);
            e.setAction(action);
            e.setOccurredAt(Instant.now());
            em.persist(e);
            tx.commit();
        } catch (RuntimeException ex) {
            tx.rollback();
            throw ex;
        }
    }
}

