package com.acme.files.security;

import org.springframework.security.access.AccessDeniedException;

/**
 * Authorises file downloads based on ownership or admin role.
 */
public class FileDownloadPolicy {

    private final FileMetadataRepository metadata;
    private final StaffDirectory staff;

    public FileDownloadPolicy(FileMetadataRepository metadata, StaffDirectory staff) {
        this.metadata = metadata;
        this.staff = staff;
    }

    public void assertMayDownload(String userId, String fileId) {
        FileMetadata m = metadata.require(fileId);
        if (m.getOwnerId().equals(userId)) {
            return;
        }
        if (staff.hasRole(userId, "DATA_ADMIN")) {
            return;
        }
        throw new AccessDeniedException("User " + userId + " may not download file " + fileId);
    }
}

