/* temp_file_cleanup.c - delete temporary uploads older than 24 hours */
#include <stdio.h>
#include "files_db.h"

int cleanup_temp_files(time_t cutoff) {
    db_cursor_t *cur = NULL;
    if (db_open_temp_files_cursor(&cur, cutoff) != DB_OK) return -1;

    int deleted = 0;
    file_row_t row;
    while (db_file_cursor_next(cur, &row) == DB_OK) {
        if (row.uploaded_at >= cutoff) continue;
        if (db_storage_delete(row.storage_key) != DB_OK) continue;
        db_mark_file_deleted(row.file_id);
        deleted++;
    }
    db_close_cursor(cur);
    return deleted;
}

